def priority(op):
  if op in '+-': return 1
  if op in '*/': return 2
  return 0

def process(st, op):
  r = st.pop(); l = st.pop()
  按 op 计算 l (op) r 压回

def evaluate(s):
  st, ops = [], []
  for ch in s:
    if ch.isdigit(): st.push(int(ch))
    elif ch == '(': ops.push(ch)
    elif ch == ')':
      while ops.top() != '(': process(st, ops.pop())
      ops.pop()  # 丢弃左括号
    else:
      while ops and priority(ops.top()) >= priority(ch):
        process(st, ops.pop())
      ops.push(ch)
  while ops: process(st, ops.pop())
  return st.top()

