def evaluate(expr):
    """双栈法求中缀表达式值, 支持 + - * / 与括号。
    数字可为多位数; 除法为向下取整(竞赛常用)。
    """
    st = []
    ops = []
    prec = {'+': 1, '-': 1, '*': 2, '/': 2}

    def apply(op):
        r = st.pop()
        l = st.pop()
        if op == '+':
            st.append(l + r)
        elif op == '-':
            st.append(l - r)
        elif op == '*':
            st.append(l * r)
        elif op == '/':
            st.append(l // r)

    i = 0
    n = len(expr)
    while i < n:
        c = expr[i]
        if c == ' ':
            i += 1
            continue
        if c.isdigit():
            num = 0
            while i < n and expr[i].isdigit():
                num = num * 10 + int(expr[i])
                i += 1
            st.append(num)
            continue
        if c == '(':
            ops.append(c)
        elif c == ')':
            while ops and ops[-1] != '(':
                apply(ops.pop())
            ops.pop()  # 移除 '('
        elif c in prec:
            while ops and ops[-1] != '(' and prec[ops[-1]] >= prec[c]:
                apply(ops.pop())
            ops.append(c)
        else:
            raise ValueError(f'未知字符: {c}')
        i += 1
    while ops:
        apply(ops.pop())
    return st[-1]


def to_rpn(expr):
    """中缀转后缀(逆波兰), 演示转换过程。"""
    out = []
    ops = []
    prec = {'+': 1, '-': 1, '*': 2, '/': 2}
    for c in expr:
        if c == ' ':
            continue
        if c.isdigit():
            out.append(c)
        elif c == '(':
            ops.append(c)
        elif c == ')':
            while ops and ops[-1] != '(':
                out.append(ops.pop())
            ops.pop()
        else:
            while ops and ops[-1] != '(' and prec[ops[-1]] >= prec[c]:
                out.append(ops.pop())
            ops.append(c)
    while ops:
        out.append(ops.pop())
    return ''.join(out)


if __name__ == '__main__':
    assert evaluate('3+2*2') == 7
    assert evaluate('(1+2)*3') == 9
    assert evaluate('20/(4+1)') == 4          # 20//5
    assert evaluate('1+2+3') == 6
    assert evaluate('2*(3+4)-5') == 9


    assert to_rpn('3+2*2') == '322*+'
    assert to_rpn('(1+2)*3') == '12+3*'

    # 与 Python 结果对照的复杂表达式(非负整除场景)
    for s in ['2+3*4-6/2', '10-2-3', '4/(2)+6']:
        assert evaluate(s) == eval(s.replace('/', '//')), s

    print('evaluate(3+2*2)  =', evaluate('3+2*2'))
    print('evaluate((1+2)*3) =', evaluate('(1+2)*3'))
    print('evaluate(20/(4+1))=', evaluate('20/(4+1)'))
    print('RPN of 3+2*2     =', to_rpn('3+2*2'))
    print('RPN of (1+2)*3   =', to_rpn('(1+2)*3'))
    print('All expression-eval tests passed!')
